import React,{useEffect,useState}from"react";

function parseFairwasUrl(value){
 const raw=String(value||"").trim();
 const match=raw.match(/^([a-z][a-z0-9+.-]*):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
 if(!match)return null;
 return{protocol:match[1].toLowerCase(),hostname:match[2].toLowerCase(),pathname:match[3]||"/",search:match[4]||"",hash:match[5]||""};
}

function navigate(path,onNavigate){const url="httc://createpage.fair"+path;if(typeof onNavigate==="function")onNavigate(url);else window.dispatchEvent(new CustomEvent("fairwas:navigate",{detail:url}))}

const publicRoutes=[
 ["/","Inicio"],
 ["/registry","Registro"],
 ["/landscape","Landscape"]
];
const privateRoutes=[
 ["/my/sites","Mis sitios"],
 ["/my/profile","Mi perfil"],
 ["/my/databases","Mis bases de datos"],
 ["/my/servers","Mis servidores"],
 ["/init","Crear sitio"],
 ["/editor","Estudio web"],
 ["/ide","Editor de código"],
 ["/workers","Workers"]
];

async function api(action,options){
 const [name,...extra]=String(action).split("&");
 const query=["action="+encodeURIComponent(name),...extra].join("&");
 const r=await fetch("/api/createpage?"+query,options);
 const d=await r.json().catch(()=>({}));
 if(!r.ok||!d.ok)throw new Error(d.detail||d.error||"request_failed");
 return d;
}

export default function CreatePage({url,onNavigate}){
 let parsed;try{parsed=new URL(url)}catch{parsed=null}
 const host=parsed?.hostname||"createpage.fair";
 const path=(parsed?.pathname||"/")+(parsed?.search||"");
 if(host==="docs.createpage.fair")return <DocsPage path={path}/>;
 return <Workspace path={path} onNavigate={onNavigate}/>;
}

function Layout({path,children,hasAccount,onNavigate}){
 const go=p=>navigate(p,onNavigate);
 const routes=hasAccount?privateRoutes:publicRoutes;
 return <section className="cp-shell">
  <aside className="cp-side">
   <div className="cp-brand"><span>CP</span><div><b>CreatePage</b><small>HTTC workspace</small></div></div>
   <nav>{routes.map(([p,label])=><button key={p} className={path===p?"active":""} onClick={()=>go(p)}>{label}</button>)}</nav>
   <div className="cp-side-foot">{hasAccount?"Cuenta de desarrollador registrada":"Sin cuenta de desarrollador"}<br/><b>HTTC · Pages · Server · Database</b></div>
  </aside>
  <div className="cp-content">{children}</div>
 </section>
}

function Workspace({path,onNavigate}){
 const[sites,setSites]=useState([]),[dbs,setDbs]=useState([]),[servers,setServers]=useState([]),[registry,setRegistry]=useState(null),[workers,setWorkers]=useState([]);
 const[error,setError]=useState("");
 const[loading,setLoading]=useState(true);
 const hasAccount=Boolean(registry?.developer?.developer_id);
 const reload=async()=>{
  setLoading(true);
  try{
   const r=await api("registry");
   setRegistry(r);
   if(r.developer){
    const [s,d,v,w]=await Promise.all([api("sites"),api("databases"),api("servers"),api("workers")]);
    setSites(s.items||[]);setDbs(d.items||[]);setServers(v.items||[]);setWorkers(w.items||[]);
   }else{
    setSites([]);setDbs([]);setServers([]);setWorkers([]);
   }
   setError("");
  }catch(e){setError(e.message)}
  finally{setLoading(false)}
 };
 useEffect(()=>{reload();const handler=()=>reload();window.addEventListener("fairwas:createpage-reload",handler);return()=>window.removeEventListener("fairwas:createpage-reload",handler)},[]);
 const routePath=path.split("?")[0];
 const privatePath=privateRoutes.some(([p])=>p===routePath);
 const effectivePath=privatePath&&!hasAccount?"/registry":routePath;
 const editorSiteId=new URLSearchParams(path.split("?")[1]||"").get("site_id")||"";
 const page=loading?<div className="cp-card cp-empty">Comprobando tu cuenta de desarrollador…</div>:
  effectivePath==="/" ? <Dashboard sites={sites} dbs={dbs} servers={servers} workers={workers} onNavigate={onNavigate}/>:
  effectivePath==="/init"?<Init onDone={reload}/>:
  effectivePath==="/editor"?<Studio onNavigate={onNavigate} onDone={reload}/>:
  effectivePath==="/my/sites"?<Sites sites={sites} onNavigate={onNavigate} onRefresh={reload}/>:
  effectivePath==="/my/databases"?<Databases dbs={dbs}/>:
  effectivePath==="/my/servers"?<Servers servers={servers}/>:
  effectivePath==="/registry"?<Registry data={registry}/>:
  effectivePath==="/landscape"?<Landscape data={registry}/>:
  effectivePath==="/workers"?<Workers workers={workers}/>:
  effectivePath==="/ide"?<Editor siteId={editorSiteId}/>:
  effectivePath==="/my/profile"?<Profile data={registry}/>:<NotFound/>;
 return <Layout path={effectivePath} hasAccount={hasAccount} onNavigate={onNavigate}>{error&&<div className="cp-error">{error}</div>}{page}</Layout>
}

function Head({eyebrow,title,text}){return <header className="cp-head"><div><small>{eyebrow}</small><h1>{title}</h1>{text&&<p>{text}</p>}</div></header>}
function Dashboard({sites,dbs,servers,workers,onNavigate}){return <><div className="cp-welcome"><div><span className="cp-kicker">CREATEPAGE STUDIO · HTTC</span><h1>Tu próximo sitio empieza aquí.</h1><p>Diseña, construye y publica páginas web desde un único estudio creativo.</p><div className="cp-welcome-actions"><button type="button" className="cp-primary" onClick={()=>navigate("/editor",onNavigate)}>✦ Abrir el estudio visual ↗</button><button type="button" className="cp-secondary" onClick={()=>navigate("/ide",onNavigate)}>Abrir editor de código</button></div></div><div className="cp-welcome-art"><div className="cp-art-window"><div className="cp-art-dots"><i/><i/><i/></div><div className="cp-art-layout"><small>YOUR NEXT BIG IDEA</small><b>Build something<br/>remarkable.</b><span/><div className="cp-art-cards"><i/><i/><i/></div></div></div><div className="cp-art-chip">✦ Studio ready</div></div></div><div className="cp-section-heading"><div><small>OVERVIEW</small><h2>Tu espacio de trabajo</h2></div><button type="button" onClick={()=>navigate("/my/sites",onNavigate)}>Ver todos los sitios ↗</button></div><div className="cp-grid four"><Stat n={sites.length} t="Sitios publicados"/><Stat n={dbs.length} t="Bases de datos"/><Stat n={servers.length} t="Servidores"/><Stat n={workers.length} t="Workers"/></div><div className="cp-section-heading"><div><small>QUICK START</small><h2>Continúa creando</h2></div></div><div className="cp-grid three"><button className="cp-action-card" onClick={()=>navigate("/editor",onNavigate)}><span>✦</span><b>Diseñador visual</b><small>Compón tu página con secciones y estilos.</small><i>Empezar a diseñar ↗</i></button><button className="cp-action-card" onClick={()=>navigate("/init",onNavigate)}><span>＋</span><b>Nuevo proyecto</b><small>Configura el dominio y crea un sitio publicable.</small><i>Crear proyecto ↗</i></button><button className="cp-action-card" onClick={()=>navigate("/ide",onNavigate)}><span>⌘</span><b>Editor de código</b><small>Importa archivos y ajusta el código fuente.</small><i>Abrir editor ↗</i></button></div></>}
function Stat({n,t}){return <div className="cp-card cp-stat"><b>{n}</b><span>{t}</span></div>}
function Sites({sites,onNavigate,onRefresh}){
 const[stats,setStats]=useState({});
 const[busy,setBusy]=useState({});
 const[errors,setErrors]=useState({});
 const visitStats=async site=>{setBusy(v=>({...v,[site.site_id]:true}));setErrors(v=>({...v,[site.site_id]:""}));try{const d=await api("visits&site_id="+encodeURIComponent(site.site_id));setStats(v=>({...v,[site.site_id]:d}))}catch(e){setErrors(v=>({...v,[site.site_id]:e.message}))}finally{setBusy(v=>({...v,[site.site_id]:false}))}};
 const unpublish=async site=>{if(!window.confirm("¿Despublicar "+site.hostname+"? Dejará de estar disponible para los visitantes, pero podrás volver a publicarlo editándolo."))return;setBusy(v=>({...v,[site.site_id]:true}));setErrors(v=>({...v,[site.site_id]:""}));try{await api("unpublish",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({site_id:site.site_id})});setStats(v=>({...v,[site.site_id]:undefined}));await onRefresh?.()}catch(e){setErrors(v=>({...v,[site.site_id]:e.message}))}finally{setBusy(v=>({...v,[site.site_id]:false}))}};
 const deleteSite=async site=>{if(!window.confirm("ELIMINAR DEFINITIVAMENTE "+site.hostname+"? Se borrarán los archivos, la configuración, las bases de datos y el historial de visitas. Esta acción no se puede deshacer."))return;setBusy(v=>({...v,[site.site_id]:true}));setErrors(v=>({...v,[site.site_id]:""}));try{await api("delete-site",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({site_id:site.site_id})});setStats(v=>({...v,[site.site_id]:undefined}));await onRefresh?.()}catch(e){setErrors(v=>({...v,[site.site_id]:e.message}));setBusy(v=>({...v,[site.site_id]:false}))}};
 return <><Head eyebrow="MY / SITES" title="Mis sitios" text="Administra publicación, visitas y eliminación de tus páginas."/><div className="cp-list">{sites.map(s=><div className="cp-card cp-site-admin" key={s.site_id}><div className="cp-row"><div><b>{s.title}</b><small>httc://{s.hostname}</small></div><span className="cp-pill">{s.status}</span></div><div className="cp-site-actions"><button type="button" onClick={()=>navigate("/ide?site_id="+encodeURIComponent(s.site_id),onNavigate)}>Editar</button><button type="button" disabled={busy[s.site_id]} onClick={()=>stats[s.site_id]?setStats(v=>({...v,[s.site_id]:undefined})):visitStats(s)}>{busy[s.site_id]?"Consultando…":stats[s.site_id]?"Ocultar visitas":"Consultar visitas"}</button>{s.status==="published"&&<button type="button" disabled={busy[s.site_id]} onClick={()=>unpublish(s)}>Despublicar</button>}<button type="button" className="cp-site-danger" disabled={busy[s.site_id]} onClick={()=>deleteSite(s)}>Eliminar página</button></div>{errors[s.site_id]&&<div className="cp-error">{errors[s.site_id]}</div>}{stats[s.site_id]&&<div className="cp-visits"><div className="cp-visits-metrics"><div><b>{stats[s.site_id].total}</b><span>Visitas registradas</span></div><div><b>{stats[s.site_id].last30Days}</b><span>Últimos 30 días</span></div><div><b>{stats[s.site_id].lastVisit?new Date(stats[s.site_id].lastVisit).toLocaleString():"Nunca"}</b><span>Última visita</span></div></div>{stats[s.site_id].items.length>0?<div className="cp-visits-list"><b>Últimas visitas</b>{stats[s.site_id].items.slice(0,10).map((v,i)=><div key={v.visited_at+"-"+i}><span>{v.url}</span><small>{new Date(v.visited_at).toLocaleString()}</small></div>)}</div>:<p className="cp-empty">Todavía no hay visitas registradas.</p>}</div>}</div>)}{!sites.length&&<Empty text="Todavía no hay sitios."/>}</div></>
}


function ApiEndpoints({sites}){
 const[siteId,setSiteId]=useState(sites[0]?.site_id||"");
 const[items,setItems]=useState([]);
 const[name,setName]=useState("Nuevo endpoint");
 const[path,setPath]=useState("/api/hello/:name");
 const[method,setMethod]=useState("GET");
 const[status,setStatus]=useState("200");
 const[response,setResponse]=useState(JSON.stringify({ok:true,message:"Hola {{params.name}}"},null,2));
 const[busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState("");
 useEffect(()=>{if(siteHostname)setDomain("api."+siteHostname);if(siteId){setName((siteHostname||"mi-sitio")+" API");setSlug(((siteHostname||"mi-sitio").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")+"-"+siteId.slice(0,6)).slice(0,64))}},[siteId,siteHostname]);
 const site=sites.find(s=>s.site_id===siteId);
 const load=async id=>{
  if(!id){setItems([]);return}
  setBusy(true);setError("");
  try{const r=await fetch("/api/endpoints?action=list&site_id="+encodeURIComponent(id));const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.detail||d.error||"request_failed");setItems(d.items||[])}
  catch(e){setError(e.message)}
  finally{setBusy(false)}
 };
 useEffect(()=>{if(!siteId&&sites[0]?.site_id)setSiteId(sites[0].site_id)},[sites,siteId]);
 useEffect(()=>{load(siteId)},[siteId]);
 const create=async()=>{
  setBusy(true);setError("");setNotice("");
  let jsonResponse;try{jsonResponse=JSON.parse(response)}catch{setBusy(false);setError("La respuesta debe ser JSON válido.");return}
  try{
   const r=await fetch("/api/endpoints?action=create",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({site_id:siteId,name,path,method,response_status:Number(status),response_json:jsonResponse})});
   const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.detail||d.error||"request_failed");
   setItems(v=>[d.endpoint,...v]);setNotice("Endpoint creado.");setName("Nuevo endpoint");setPath("/api/hello/:name");
  }catch(e){setError(e.message)}
  finally{setBusy(false)}
 };
 const remove=async item=>{
  if(!window.confirm("¿Eliminar el endpoint "+item.method+" "+item.path+"?"))return;
  setBusy(true);setError("");setNotice("");
  try{const r=await fetch("/api/endpoints?action=delete",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({site_id:siteId,id:item.id})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.detail||d.error||"request_failed");setItems(v=>v.filter(x=>x.id!==item.id));setNotice("Endpoint eliminado.")}
  catch(e){setError(e.message)}
  finally{setBusy(false)}
 };
 return <><Head eyebrow="API / ENDPOINTS" title="APIs y endpoints" text="Define rutas HTTP para cada sitio y responde con JSON sin crear un servidor desde cero."/>
  {!sites.length?<div className="cp-card cp-empty">Primero crea un sitio en CreatePage.</div>:<>
   <div className="cp-card cp-form">
    <label>Sitio publicado<select value={siteId} onChange={e=>setSiteId(e.target.value)}>{sites.map(s=><option key={s.site_id} value={s.site_id}>{s.hostname} · {s.status}</option>)}</select></label>
    {site&&<p className="cp-empty">URL base: <b>httc://{site.hostname}</b></p>}
    <div className="cp-grid two">
     <label>Nombre del endpoint<input value={name} onChange={e=>setName(e.target.value)} maxLength={80}/></label>
     <label>Método HTTP<select value={method} onChange={e=>setMethod(e.target.value)}>{["GET","POST","PUT","PATCH","DELETE"].map(m=><option key={m}>{m}</option>)}</select></label>
     <label>Ruta<input value={path} onChange={e=>setPath(e.target.value)} placeholder="/api/users/:id"/></label>
     <label>Código HTTP<select value={status} onChange={e=>setStatus(e.target.value)}>{[200,201,202,204,400,401,403,404,409,422,429,500,503].map(n=><option key={n} value={n}>{n}</option>)}</select></label>
    </div>
    <label>Respuesta JSON<textarea rows={7} value={response} onChange={e=>setResponse(e.target.value)} spellCheck={false}/></label>
    <small>Variables: {"{{params.id}}"}, {"{{query.search}}"} y {"{{body.name}}"}.</small>
    <button type="button" className="cp-primary" disabled={busy||!siteId} onClick={create}>{busy?"Guardando…":"＋ Crear endpoint"}</button>
    {error&&<div className="cp-error">{error}</div>}{notice&&<p>{notice}</p>}
   </div>
   <div className="cp-section-heading"><div><small>ROUTES</small><h2>Endpoints de {site?.hostname||"tu sitio"}</h2></div><button type="button" onClick={()=>load(siteId)} disabled={busy}>↻ Actualizar</button></div>
   <div className="cp-list">{items.map(item=><div className="cp-card" key={item.id}><div className="cp-row"><div><b>{item.name}</b><small>{item.method} · {item.path}</small></div><span className="cp-pill">{item.response_status}</span></div><pre className="cp-api-preview">{item.response_json}</pre><div className="cp-site-actions"><button type="button" className="cp-site-danger" disabled={busy} onClick={()=>remove(item)}>Eliminar endpoint</button></div><small>URL pública: httc://{item.hostname}{item.path}</small></div>)}{!items.length&&<Empty text={busy?"Cargando endpoints…":"Todavía no has creado endpoints para este sitio."}/>}</div>
  </>}
 </>;
}

function Databases({dbs}){return <><Head eyebrow="MY / DATABASES" title="Mis bases de datos" text="Recursos de datos registrados en Database."/><div className="cp-list">{dbs.map(d=><div className="cp-card cp-row" key={d.id}><div><b>{d.name}</b><small>{d.engine} · {d.status}</small></div><span className="cp-pill">{d.site_id?"Conectada":"Libre"}</span></div>)}{!dbs.length&&<Empty text="No hay bases de datos."/>}</div></>}
function Servers({servers}){return <><Head eyebrow="MY / SERVERS" title="Mis servidores" text="Dominios y orígenes registrados en Server."/><div className="cp-list">{servers.map(s=><div className="cp-card cp-row" key={s.id}><div><b>{s.hostname}</b><small>{s.protocol} · {s.origin}</small></div><span className="cp-pill">{s.status}</span></div>)}{!servers.length&&<Empty text="No hay servidores."/>}</div></>}
function Registry({data}){const[displayName,setDisplayName]=useState(data?.developer?.display_name||"");const[email,setEmail]=useState(data?.developer?.email||"");const[ok,setOk]=useState(false);const[error,setError]=useState("");useEffect(()=>{setDisplayName(data?.developer?.display_name||"");setEmail(data?.developer?.email||"")},[data?.developer?.display_name,data?.developer?.email]);const saveDeveloper=async()=>{setOk(false);setError("");try{await api("developer",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({display_name:displayName,email})});setOk(true);window.dispatchEvent(new CustomEvent("fairwas:createpage-reload"))}catch(e){setError(e.message)}};return <><Head eyebrow="REGISTRY" title="Cuenta de desarrollador" text="Registra tu cuenta para vincular y publicar tus páginas en CreatePage."/><div className="cp-grid two"><div className="cp-card cp-form"><h3>Registro de desarrollador</h3><label>Nombre<input placeholder="Mi cuenta" value={displayName} onChange={e=>setDisplayName(e.target.value)}/></label><label>Email<input type="email" placeholder="tu@email.com" value={email} onChange={e=>setEmail(e.target.value)}/></label><button onClick={saveDeveloper}>Registrar cuenta</button>{ok&&<small>Cuenta registrada. El ID de desarrollador se genera automáticamente.</small>}{error&&<div className="cp-error">{error}</div>}</div><div className="cp-card"><h3>Páginas vinculadas</h3>{data?.developer&&<><p className="cp-line"><b>{data.developer.display_name}</b><span>{data.developer.developer_id}</span></p><p className="cp-line"><b>Email</b><span>{data.developer.email||"Sin email"}</span></p><small>El ID de desarrollador es permanente para esta cuenta.</small></>}{data?.sites?.map(s=><p className="cp-line" key={s.site_id}><b>{s.hostname}</b><span>{s.status}</span></p>)}{!data?.sites?.length&&<p className="cp-empty">Registra tu cuenta y las nuevas páginas quedarán vinculadas aquí.</p>}</div></div></>}
function Landscape({data}){return <><Head eyebrow="LANDSCAPE" title="Infraestructura" text="El recorrido real de un sitio publicado."/><div className="cp-landscape"><Node t="CreatePage" s="Control"/><i>↓</i><Node t="Pages" s="Sitio + archivos"/><i>↔</i><Node t="Server" s="Dominio + origen"/><i>↓</i><Node t="HTTC" s={data?.sites?.length?data.sites.length+" sitios publicados":"Sin sitios publicados"}/></div></>}
function Node({t,s}){return <div className="cp-node"><b>{t}</b><span>{s}</span></div>}
function Workers({workers}){return <><Head eyebrow="WORKERS" title="Workers" text="Workers asociados al ecosistema CreatePage."/><div className="cp-list">{workers.map(w=><div className="cp-card cp-row" key={w.id}><div><b>{w.name}</b><small>{w.status}</small></div></div>)}{!workers.length&&<Empty text="No hay Workers todavía."/>}</div></>}
function Profile({data}){const account=data?.developer;const[name,setName]=useState(account?.display_name||"Fairwas user");const[ok,setOk]=useState(false);const[error,setError]=useState("");useEffect(()=>{setName(account?.display_name||"Fairwas user");setOk(false);setError("")},[account?.display_name]);const save=async()=>{setOk(false);setError("");try{await api("profile",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({display_name:name})});setOk(true);window.dispatchEvent(new CustomEvent("fairwas:createpage-reload"))}catch(e){setError(e.message)}};return <><Head eyebrow="MY / PROFILE" title="Mi perfil" text="Identidad de tu cuenta de desarrollador."/><div className="cp-grid two"><div className="cp-card cp-form"><label>Nombre<input value={name} onChange={e=>setName(e.target.value)}/></label><button type="button" onClick={save}>Guardar perfil</button>{ok&&<small>Guardado.</small>}{error&&<div className="cp-error">{error}</div>}</div><div className="cp-card"><h3>Cuenta</h3><p className="cp-line"><b>User ID</b><span>{account?.user_id||"—"}</span></p><p className="cp-line"><b>Developer ID</b><span>{account?.developer_id||"—"}</span></p><p className="cp-line"><b>Email</b><span>{account?.email||"—"}</span></p><p className="cp-line"><b>Estado</b><span>{account?.status||"—"}</span></p><p className="cp-line"><b>Creada</b><span>{account?.created_at||"—"}</span></p></div></div></>}
function readIdeDraft(siteId){try{const value=JSON.parse(localStorage.getItem("fairwas:ide-draft:"+(siteId||"new"))||"null");return value&&typeof value==="object"?value:null}catch{return null}}

function Editor({siteId=""}){
  const [newDraftId]=useState(()=>siteId?"":"new-"+Date.now()+"-"+Math.random().toString(36).slice(2));
  const draft=siteId?readIdeDraft(siteId):null;
  const draftKey="fairwas:ide-draft:"+(siteId||newDraftId);
 const[files,setFiles]=useState(()=>Array.isArray(draft?.files)&&draft.files.length?draft.files:[{path:"/routes/mainpage/index.html",content:"<!doctype html>\n<html>\n<head><meta charset=\"utf-8\"><title>Inicio</title></head>\n<body><h1>Hola desde CreatePage</h1><p>Ruta principal: /</p></body>\n</html>"}]);
 const[folders,setFolders]=useState(()=>Array.isArray(draft?.folders)?draft.folders:[]);
  const[selected,setSelected]=useState(()=>draft?.selected||"/routes/mainpage/index.html");
 const[code,setCode]=useState(()=>(draft?.code??draft?.files?.find(file=>file.path===draft?.selected)?.content) || "<!doctype html>\n<html>\n<head><meta charset=\"utf-8\"><title>Inicio</title></head>\n<body><h1>Hola desde CreatePage</h1><p>Ruta principal: /</p></body>\n</html>");
 const[site,setSite]=useState(()=>draft?.site||{site_id:siteId,hostname:"",title:"Mi sitio"});
 const[build,setBuild]=useState(()=>draft?.build||{root:"/",output:"/dist",command:"npm run build"});
 const[status,setStatus]=useState("");
 const[repoUrl,setRepoUrl]=useState(()=>draft?.repoUrl||"");
 const[sourceRepo,setSourceRepo]=useState(()=>Boolean(draft?.sourceRepo));
 const[migrateUrl,setMigrateUrl]=useState(()=>draft?.migrateUrl||"");
 const[loaded,setLoaded]=useState(!siteId);
 const activeSiteId=siteId||site.site_id||"";
 const[pageDatabases,setPageDatabases]=useState([]);
 const[newDatabaseName,setNewDatabaseName]=useState("");
 const[selectedDatabase,setSelectedDatabase]=useState("");
 const[sqlText,setSqlText]=useState("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT);");
 const[sqlResult,setSqlResult]=useState(null);
 const[dbBusy,setDbBusy]=useState(false);
 const[dbError,setDbError]=useState("");
 const[dbPanelOpen,setDbPanelOpen]=useState(false);
 const[apiPanelOpen,setApiPanelOpen]=useState(false);

 const currentFiles=()=>files.map(file=>file.path===selected?{...file,content:code}:file);
 const normalizePath=raw=>{let path=String(raw||"").trim().replace(/\\/g,"/");if(!path.startsWith("/"))path="/"+path;path=path.replace(/\/+/g,"/");return path.length>1?path.replace(/\/$/,""):path};
 const pick=path=>{const file=files.find(item=>item.path===path);if(!file)return;setSelected(path);setCode(file.content)};
 useEffect(()=>{if(!siteId)return;let cancelled=false;(async()=>{setStatus("Cargando página…");try{const d=await api("site&site_id="+encodeURIComponent(siteId));if(cancelled)return;if(draft&&Array.isArray(draft.files)&&draft.files.length){setFiles(draft.files);setFolders(Array.isArray(draft.folders)?draft.folders:[]);setSelected(draft.selected||draft.files[0].path);setCode(draft.code ?? (draft.files.find(file=>file.path===(draft.selected||draft.files[0].path))?.content || ""));setSite(draft.site||{site_id:siteId,hostname:d.site?.hostname||d.project?.hostname||"",title:d.site?.title||d.project?.title||"Mi sitio"});setBuild(draft.build||{root:d.project?.build_root||"/",output:d.project?.build_output||"/dist",command:d.project?.build_command||"npm run build"});setSourceRepo(Boolean(draft.sourceRepo));setRepoUrl(draft.repoUrl||"");setMigrateUrl(draft.migrateUrl||"");setStatus("Borrador local recuperado. Tus cambios sin publicar siguen aquí.")}else{const imported=d.files||[];setFiles(imported.length?imported:[{path:"/routes/mainpage/index.html",content:""}]);const first=imported[0]||{path:"/routes/mainpage/index.html",content:""};setSelected(first.path);setCode(first.content||"");setSite({site_id:siteId,hostname:d.site?.hostname||d.project?.hostname||"",title:d.site?.title||d.project?.title||"Mi sitio"});setBuild({root:d.project?.build_root||"/",output:d.project?.build_output||"/dist",command:d.project?.build_command||"npm run build"});setStatus("Página cargada.")}setLoaded(true)}catch(error){setStatus(error instanceof Error?error.message:"No se pudo cargar la página.");setLoaded(true)}})();return()=>{cancelled=true}},[siteId]);
  useEffect(()=>{if(!loaded)return;try{const snapshot={files:files.map(file=>file.path===selected?{...file,content:code}:file),folders,selected,code,site,build,sourceRepo,repoUrl,migrateUrl,savedAt:new Date().toISOString()};localStorage.setItem(draftKey,JSON.stringify(snapshot))}catch(error){setStatus("No se pudo guardar el borrador local completo. Exporta o publica el proyecto para evitar perder cambios.")}},[draftKey,loaded,files,folders,selected,code,site,build,sourceRepo,repoUrl,migrateUrl]);
 useEffect(()=>{if(!activeSiteId||!loaded)return;let cancelled=false;(async()=>{try{const d=await api("db-list&site_id="+encodeURIComponent(activeSiteId));if(!cancelled){setPageDatabases(d.items||[]);setDbError("");if(!selectedDatabase&&d.items?.length)setSelectedDatabase(d.items[0].name)}}catch(e){if(!cancelled)setDbError(e.message)}})();return()=>{cancelled=true}},[activeSiteId,loaded]);
 const createPageDatabase=async()=>{setDbError("");setSqlResult(null);if(!activeSiteId){setDbError("Publica primero el sitio para poder asociarle bases de datos.");return}setDbBusy(true);try{const d=await api("db-create",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({site_id:activeSiteId,name:newDatabaseName})});setPageDatabases(current=>[...current,d.database]);setSelectedDatabase(d.database.name);setNewDatabaseName("");setDbError("Base de datos SQLite creada.");}catch(e){setDbError(e.message)}finally{setDbBusy(false)}};
 const runDatabaseSql=async()=>{setDbError("");setSqlResult(null);if(!site.hostname||!selectedDatabase){setDbError("Selecciona una base de datos y confirma el dominio del sitio.");return}setDbBusy(true);try{const d=await api("db-query",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({hostname:site.hostname,database:selectedDatabase,sql:sqlText})});setSqlResult(d);const list=await api("db-list&site_id="+encodeURIComponent(activeSiteId));setPageDatabases(list.items||[]);const client="\n<script id=\"fairwas-database-client\">\nwindow.fairwasDB = { database: "+JSON.stringify(selectedDatabase)+", hostname: "+JSON.stringify(site.hostname)+", query: async function(sql, params = []) { const response = await fetch(\"/api/createpage?action=db-query\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ hostname: this.hostname, database: this.database, sql, params }) }); const result = await response.json(); if (!response.ok || !result.ok) throw new Error(result.detail || result.error || \"database_query_failed\"); return result; } };\n</script>\n";const next=currentFiles();let target=next.find(file=>file.path==="/routes/mainpage/index.html")||next.find(file=>file.path==="/index.html")||next.find(file=>/\.html?$/i.test(file.path));if(!target){target={path:"/routes/mainpage/index.html",content:"<!doctype html><html><head><meta charset=\"utf-8\"></head><body></body></html>"};next.push(target)}const marker=/<script id="fairwas-database-client">[\s\S]*?<\/script>/i;target.content=marker.test(target.content||"")?(target.content||"").replace(marker,client.trim()):(target.content||"").includes("</body>")?(target.content||"").replace("</body>",client+"</body>"):(target.content||"")+client;setFiles(next);if(target.path===selected)setCode(target.content);setStatus("SQL ejecutado. La conexión a "+selectedDatabase+" se ha integrado automáticamente en "+target.path+" como window.fairwasDB.");}catch(e){setDbError(e.message)}finally{setDbBusy(false)}};
 const deletePageDatabase=async db=>{if(!window.confirm("¿Eliminar la base de datos "+db.name+" y todas sus tablas?"))return;setDbError("");try{await api("db-delete",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({site_id:activeSiteId,database_id:db.id})});setPageDatabases(current=>current.filter(x=>x.id!==db.id));if(selectedDatabase===db.name)setSelectedDatabase("");setDbError("Base de datos eliminada.")}catch(e){setDbError(e.message)}};

 const addFile=()=>{const raw=window.prompt("Ruta del archivo","/src/app.js");if(!raw)return;const path=normalizePath(raw);if(path.endsWith("/")){setStatus("Usa + Carpeta para crear directorios.");return}if(files.some(file=>file.path===path)){setStatus("Ese archivo ya existe.");return}const next=[...currentFiles(),{path,content:""}];setFiles(next);setSelected(path);setCode("");setStatus("Archivo creado.")};
 const addFolder=()=>{const raw=window.prompt("Ruta de la carpeta","/src/components");if(!raw)return;const path=normalizePath(raw).replace(/\/$/,"");if(!path||path==="/"){setStatus("Introduce una carpeta válida.");return}if(folders.includes(path)||files.some(file=>file.path===path||file.path.startsWith(path+"/"))){setStatus("Esa carpeta ya existe.");return}setFolders(current=>[...current,path]);setStatus("Carpeta creada: "+path+". No se ha generado ningún archivo .gitkeep.")};
 const remove=()=>{if(!selected)return;const file=files.find(item=>item.path===selected);if(!file)return;if(!window.confirm("¿Eliminar "+file.path+"?"))return;const next=files.filter(item=>item.path!==selected);if(!next.length){setStatus("El proyecto necesita al menos un archivo.");return}setFiles(next);const target=next[0];setSelected(target.path);setCode(target.content);setStatus("Archivo eliminado.")};
 const rename=()=>{if(!selected)return;const raw=window.prompt("Nueva ruta",selected);if(!raw)return;const path=normalizePath(raw);if(path===selected)return;if(files.some(file=>file.path===path)){setStatus("Ya existe un archivo con esa ruta.");return}const next=currentFiles().map(file=>file.path===selected?{...file,path}:file);setFiles(next);setSelected(path);setCode(next.find(file=>file.path===path)?.content||"");setStatus("Archivo renombrado.")};
 const importFiles=event=>{const list=Array.from(event.target.files||[]);if(!list.length)return;const mime=name=>({html:"text/html; charset=utf-8",htm:"text/html; charset=utf-8",css:"text/css; charset=utf-8",js:"text/javascript; charset=utf-8",mjs:"text/javascript; charset=utf-8",json:"application/json; charset=utf-8",svg:"image/svg+xml",txt:"text/plain; charset=utf-8",png:"image/png",jpg:"image/jpeg",jpeg:"image/jpeg",gif:"image/gif",webp:"image/webp",avif:"image/avif",ico:"image/x-icon",woff:"font/woff",woff2:"font/woff2",ttf:"font/ttf",otf:"font/otf",mp3:"audio/mpeg",wav:"audio/wav",ogg:"audio/ogg",mp4:"video/mp4",webm:"video/webm",wasm:"application/wasm"}[String(name).split(".").pop()?.toLowerCase()]||"application/octet-stream");const read=async file=>{const path="/"+(file.webkitRelativePath||file.name).replace(/^\/+/, "");const contentType=mime(path);if(contentType.startsWith("text/")||/json|javascript|svg|xml/.test(contentType))return{path,content:await file.text(),content_type:contentType};const bytes=new Uint8Array(await file.arrayBuffer());let binary="";for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return{path,content:btoa(binary),content_type:contentType,encoding:"base64"}};Promise.all(list.map(read)).then(items=>{setFiles(current=>{const map=new Map(currentFiles().map(file=>[file.path,file]));items.forEach(file=>map.set(file.path,file));return[...map.values()]});setSourceRepo(false);setStatus(items.length+" archivo"+(items.length===1?"":"s")+" importado"+(items.length===1?"":"s")+".")}).catch(error=>setStatus(error instanceof Error?error.message:"No se pudieron importar los archivos."))};
 const migrateStatic=async()=>{if(!migrateUrl.trim()){setStatus("Introduce la URL de la página estática.");return}setStatus("Migrando página estática…");try{const response=await fetch("/api/migrate",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({url:migrateUrl.trim()})});const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.detail||data.error||"migration_failed");const imported=(data.files||[]).map(file=>({...file,path:normalizePath(file.path)}));if(!imported.length){setStatus("No se encontraron archivos estáticos.");return}setFiles(imported);setSourceRepo(false);setSite(current=>({...current,hostname:data.hostname||current.hostname,title:data.title||current.title}));setSelected(imported.find(file=>file.path==="/routes/mainpage/index.html")?.path||imported.find(file=>file.path==="/index.html")?.path||imported[0].path);setCode(imported.find(file=>file.path==="/routes/mainpage/index.html")?.content||imported.find(file=>file.path==="/index.html")?.content||imported[0].content||"");setStatus("Migración estática completada: "+imported.length+" archivos.")}catch(error){setStatus(error instanceof Error?error.message:"No se pudo migrar la página.")}};
 const importRepo=async()=>{if(!repoUrl.trim()){setStatus("Introduce la URL del repositorio.");return}setStatus("Importando repositorio…");try{const data=await api("import",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({repo_url:repoUrl.trim()})});const imported=(data.files||[]).map(file=>({...file,path:normalizePath(file.path)}));if(!imported.length){setStatus("No se pudieron leer los archivos del repositorio.");return}setFiles(imported);setSourceRepo(Boolean(data.source_files));setSite(current=>({...current,hostname:data.hostname||current.hostname,title:data.title||current.title}));setSelected(imported[0].path);setCode(imported[0].content||"");setStatus(data.source_files?"Fuentes importadas, pero no compiladas. React/Vite necesita una compilación antes de poder publicarse correctamente.":"Repositorio compilado importado.")}catch(error){setStatus(error instanceof Error?error.message:"No se pudo importar el repositorio.")}};
 const save=async()=>{if(sourceRepo){setStatus("No se puede publicar este repositorio todavía: es código fuente sin compilar. Compílalo fuera de Fairwas e importa la carpeta de salida (dist/build).");return}const next=currentFiles();const index=next.find(file=>file.path==="/routes/mainpage/index.html")||next.find(file=>file.path==="/index.html");if(!index){setStatus("El proyecto necesita /routes/mainpage/index.html (ruta /) o /index.html.");return}if(!site.hostname.trim()){setStatus("Introduce un dominio antes de actualizar.");return}setStatus(siteId?"Actualizando página…":"Publicando…");try{const action=siteId?"update":"create";const data=await api(action,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...site,hostname:site.hostname.trim().toLowerCase(),html:index.content,files:next,build_root:build.root,build_output:build.output,build_command:build.command})});setFiles(next);setSite(current=>({...current,site_id:data.site_id,hostname:data.hostname||current.hostname}));setStatus(siteId?"Página actualizada: "+data.url:"Publicado: "+data.url)}catch(error){setStatus(error instanceof Error?error.message:"No se pudo guardar la página.")}};
 const tree=(()=>{const dirs=new Set(folders);files.forEach(file=>{const parts=file.path.split("/").filter(Boolean);for(let i=1;i<parts.length;i++)dirs.add("/"+parts.slice(0,i).join("/"))});const entries=[...Array.from(dirs,path=>({path,folder:true})),...files.map(file=>({path:file.path,folder:false}))];return entries.sort((a,b)=>a.path.localeCompare(b.path)||(a.folder?-1:1)).map(item=>({...item,depth:Math.max(0,item.path.split("/").filter(Boolean).length-1)}))})();
 if(!loaded)return <section className="cp-ide"><div className="cp-card cp-empty">Cargando página…</div></section>;
 return <section className="cp-ide">
  <div className="cp-ide-top"><div><small>CREATEPAGE IDE</small><h1>{siteId?"Editar página":"Editor del sitio"}</h1></div><div className="cp-ide-actions"><button type="button" onClick={addFile}>+ Archivo</button><button type="button" onClick={addFolder}>+ Carpeta</button><button type="button" onClick={rename}>Renombrar</button><button type="button" onClick={remove}>Eliminar</button><button type="button" onClick={()=>setApiPanelOpen(v=>!v)}>{apiPanelOpen?"Cerrar backend ×":"APIs / Backend ⚙"}</button><label className="cp-button">Importar carpeta<input type="file" multiple webkitdirectory="" onChange={importFiles}/></label><button type="button" onClick={save}>{siteId?"Actualizar página":"Publicar"}</button></div></div>
  <div className="cp-ide-import">{!siteId&&<><input placeholder="https://github.com/usuario/repositorio" value={repoUrl} onChange={e=>setRepoUrl(e.target.value)}/><button type="button" onClick={importRepo}>Importar Git</button><input placeholder="https://ejemplo.com/" value={migrateUrl} onChange={e=>setMigrateUrl(e.target.value)}/><button type="button" onClick={migrateStatic}>Migrar estática</button></>}<input placeholder="dominio.fair" value={site.hostname} onChange={e=>setSite(s=>({...s,hostname:e.target.value}))}/><input placeholder="Nombre del sitio" value={site.title} onChange={e=>setSite(s=>({...s,title:e.target.value}))}/><input placeholder="Raíz del proyecto /" value={build.root} onChange={e=>setBuild(x=>({...x,root:e.target.value}))}/><input placeholder="Salida /dist" value={build.output} onChange={e=>setBuild(x=>({...x,output:e.target.value}))}/><input placeholder="Comando de compilación" value={build.command} onChange={e=>setBuild(x=>({...x,command:e.target.value}))}/></div>
  <div className="cp-ide-body"><aside className="cp-files" aria-label="Explorador de archivos"><div className="cp-files-title">EXPLORADOR</div>{tree.map(item=>item.folder?<div className="cp-file-folder" style={{paddingLeft:10+item.depth*14}} key={"dir:"+item.path} title={item.path}><span aria-hidden="true">▸</span> {item.path.split("/").pop()}<small>{item.path}</small></div>:<button type="button" className={selected===item.path?"active":""} style={{paddingLeft:10+item.depth*14}} key={"file:"+item.path} onClick={()=>pick(item.path)}>{item.path.split("/").pop()||"/"}<small>{item.path}</small></button>)}</aside><div className="cp-editor-wrap"><div className="cp-editor-head"><b>{selected}</b><span aria-live="polite">{status}</span></div><textarea className="cp-editor" value={code} onChange={e=>setCode(e.target.value)} spellCheck="false" aria-label={"Editor de "+selected}/></div></div>
  <section className="cp-card cp-db-panel">
   <div className="cp-db-toggle-row"><div><small>ENV.DATABASE</small><b>Bases de datos</b><span>{pageDatabases.length}/20 · {pageDatabases.length===1?"1 base conectada":pageDatabases.length+" bases conectadas"}</span></div><button type="button" className="cp-db-toggle" aria-expanded={dbPanelOpen} onClick={()=>setDbPanelOpen(open=>!open)}>{dbPanelOpen?"Cerrar bases ×":"Abrir bases ⚙"}</button></div>
   {dbPanelOpen&&<>
   {!activeSiteId&&<div className="cp-empty">Publica primero este sitio para habilitar sus bases de datos.</div>}
   {activeSiteId&&<div className="cp-db-create"><input value={newDatabaseName} onChange={e=>setNewDatabaseName(e.target.value)} placeholder="Nombre, por ejemplo UserData" maxLength={40}/><button type="button" disabled={dbBusy||pageDatabases.length>=20} onClick={createPageDatabase}>＋ Crear SQLite</button></div>}
   <div className="cp-db-list">{pageDatabases.map(db=><div className="cp-db-item" key={db.id}><button type="button" className={selectedDatabase===db.name?"active":""} onClick={()=>{setSelectedDatabase(db.name);setSqlResult(null)}}><b>{db.name}</b><small>SQLite · {(db.tables||[]).length} tablas</small></button><button type="button" className="cp-db-delete" onClick={()=>deletePageDatabase(db)}>Eliminar</button></div>)}</div>
   {pageDatabases.length>0&&<><label className="cp-db-label">Base seleccionada<select value={selectedDatabase} onChange={e=>{setSelectedDatabase(e.target.value);setSqlResult(null)}}>{pageDatabases.map(db=><option key={db.id} value={db.name}>{db.name}</option>)}</select></label><label className="cp-db-label">Consulta SQL (SQLite)<textarea className="cp-db-sql" value={sqlText} onChange={e=>setSqlText(e.target.value)} spellCheck="false"/></label><div className="cp-db-actions"><button type="button" disabled={dbBusy} onClick={runDatabaseSql}>{dbBusy?"Ejecutando…":"Ejecutar SQL"}</button><span>Usa ? como marcador de parámetros desde el código de tu página.</span></div></>}
   {dbError&&<div className="cp-db-message">{dbError}</div>}
   {sqlResult&&<div className="cp-db-result"><b>Consulta ejecutada · {sqlResult.changes||0} cambios</b><pre>{JSON.stringify(sqlResult.results||[],null,2)}</pre></div>}
   <details className="cp-db-docs"><summary>Conexión automática desde tu página</summary><p>Al ejecutar SQL, CreatePage añade el cliente a tu HTML. Después puedes usar <code>window.fairwasDB</code> sin configurar el fetch a mano:</p><pre>{'window.fairwasDB.query("SELECT * FROM users").then(data => console.log(data.results));'}</pre><p>Para consultas parametrizadas: <code>window.fairwasDB.query("SELECT * FROM users WHERE id = ?", [userId])</code>. Usa SQLite mediante <code>env.database</code>; MySQL no está disponible en este binding D1.</p></details>
   </>}
  </section>
  {apiPanelOpen&&<section className="cp-card cp-db-panel cp-project-backend"><div className="cp-db-toggle-row"><div><small>PROJECT BACKEND</small><b>Infraestructura de esta página</b><span>{site.hostname||"Publica el sitio para activar las APIs"}</span></div><button type="button" className="cp-db-toggle" onClick={()=>setApiPanelOpen(false)}>Cerrar ×</button></div><PlatformServices siteId={activeSiteId} siteHostname={site.hostname}/></section>}
 </section>;
}
function Init({onDone}){const[f,setF]=useState({hostname:"",title:"",description:"",framework:"React + Vite",language:"JavaScript",backend:"Cloudflare Pages Functions",runtime:"Cloudflare",database_type:"SQLite",database_name:"",html:""});const[busy,setBusy]=useState(false);const[done,setDone]=useState(null);const set=(k,v)=>setF(x=>({...x,[k]:v}));const submit=async e=>{e.preventDefault();setBusy(true);try{const hostname=String(f.hostname||"").trim().toLowerCase().replace(/^https?:\/\//,"").replace(/[/?#].*$/,"");const r=await api("create",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...f,hostname})});setDone(r);onDone()}catch(e){setDone({error:e.message})}finally{setBusy(false)}};return <><Head eyebrow="INIT" title="Crear un sitio" text="Un único flujo registra el sitio, el dominio y la publicación real."/><form className="cp-card cp-form" onSubmit={submit}><div className="cp-grid two"><label>Dominio<input required placeholder="miweb.fair (sin www obligatorio)" value={f.hostname} onChange={e=>set("hostname",e.target.value)}/><small>Escribe miweb.fair o www.miweb.fair. Ambos formatos son válidos.</small></label><label>Nombre<input required placeholder="Mi web" value={f.title} onChange={e=>set("title",e.target.value)}/></label><label>Framework<select value={f.framework} onChange={e=>set("framework",e.target.value)}><option>React + Vite</option><option>Vanilla</option><option>Custom</option></select></label><label>Lenguaje<select value={f.language} onChange={e=>set("language",e.target.value)}><option>JavaScript</option><option>TypeScript</option><option>HTML</option></select></label><label>Backend<input value={f.backend} onChange={e=>set("backend",e.target.value)}/></label><label>Runtime<input value={f.runtime} onChange={e=>set("runtime",e.target.value)}/></label><label>Base de datos<input placeholder="UserData" value={f.database_name} onChange={e=>set("database_name",e.target.value)}/><small>Motor: SQLite</small></label><label>Logo URL<input value={f.logo_url||""} onChange={e=>set("logo_url",e.target.value)}/></label></div><label>Descripción<textarea value={f.description} onChange={e=>set("description",e.target.value)} /></label><label>index.html<textarea className="codebox" value={f.html} onChange={e=>set("html",e.target.value)} /></label><div className="cp-publishbar"><span>Protocolo <b>HTTC</b> · destino Pages + Server</span><button disabled={busy}>{busy?"Publicando…":"Crear y publicar"}</button></div>{done?.error&&<div className="cp-error">{done.error}</div>}{done?.status==="published"&&<div className="cp-success">Publicado: <b>{done.url}</b> · {done.version}</div>}</form></>}

function Studio({onNavigate,onDone}){
 const [site,S]=useState({title:"Forma Studio",hostname:"forma.fair",eyebrow:"DISEÑO DIGITAL · SIN LÍMITES",headline:"Ideas brillantes.\nExperiencias memorables.",description:"Creamos experiencias digitales que convierten ideas ambiciosas en marcas inolvidables.",cta:"Hablemos de tu proyecto",accent:"#b9f36b",background:"#10120f",text:"#f6f7f2"});
 const [sections,SS]=useState([{id:2,type:"features",title:"Todo lo que necesitas para destacar",text:"Una experiencia cuidada de principio a fin."},{id:3,type:"about",title:"Diseñado alrededor de tu idea",text:"Estrategia, diseño y tecnología en perfecta sintonía."}]);
 const [active,A]=useState(1),[view,V]=useState("desktop"),[busy,B]=useState(false),[msg,M]=useState(""),[err,E]=useState("");
 const esc=s=>String(s||"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
 const html=()=>`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(site.title)}</title><meta name="description" content="${esc(site.description)}"><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:${site.background};color:${site.text};font-family:Inter,system-ui,-apple-system,sans-serif}a{color:inherit;text-decoration:none}.nav{max-width:1180px;margin:auto;padding:28px 6%;display:flex;justify-content:space-between;align-items:center}.brand{font-weight:800;font-size:20px}.brand span,.eyebrow{color:${site.accent}}.nav a:last-child,.cta{background:${site.accent};color:#171b12;padding:13px 19px;border-radius:999px;font-weight:750;font-size:13px}.hero{max-width:1180px;margin:auto;padding:90px 6% 110px}.eyebrow{font-size:11px;letter-spacing:.17em;font-weight:800}.hero h1{white-space:pre-line;max-width:850px;font-size:clamp(42px,8vw,92px);line-height:.99;letter-spacing:-.075em;margin:24px 0}.hero p{max-width:570px;color:#a5aa9e;line-height:1.8;font-size:17px;margin-bottom:30px}.section{max-width:1180px;margin:auto;padding:70px 6%;border-top:1px solid #ffffff17}.section h2{font-size:clamp(27px,4vw,46px);letter-spacing:-.05em;max-width:700px}.section p{color:#a5aa9e;line-height:1.8;max-width:650px}.features{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:30px}.feature{border:1px solid #ffffff20;background:#ffffff07;border-radius:20px;padding:25px;min-height:155px}.feature span{color:${site.accent};font-size:24px}.feature h3{font-size:17px}.feature p{font-size:13px}@media(max-width:650px){.hero{padding-top:60px}.features{grid-template-columns:1fr}.nav{padding-top:20px}.hero p{font-size:15px}}</style></head><body><nav class="nav"><div class="brand">${esc(site.title)}<span>✳</span></div><a href="#contact">${esc(site.cta)}</a></nav><main><section class="hero"><div class="eyebrow">${esc(site.eyebrow)}</div><h1>${esc(site.headline)}</h1><p>${esc(site.description)}</p><a class="cta" href="#contact">${esc(site.cta)} ↗</a></section>${sections.map((s,i)=>s.type==="features"?`<section class="section"><div class="eyebrow">0${i+1} / QUÉ HACEMOS</div><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p><div class="features">${["Diseño con intención","Tecnología moderna","Detalles que importan"].map((x,j)=>`<article class="feature"><span>0${j+1}</span><h3>${x}</h3><p>Una solución pensada para tus objetivos y tu identidad.</p></article>`).join("")}</div></section>`:`<section class="section" id="contact"><div class="eyebrow">0${i+2} / SOBRE NOSOTROS</div><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p><a class="cta" href="mailto:hola@example.com">${esc(site.cta)} ↗</a></section>`).join("")}</main><footer class="section"><div class="brand">${esc(site.title)}<span>✳</span></div><p>Diseñado con CreatePage Studio.</p></footer></body></html>`;
 const add=type=>{const id=Date.now();SS(x=>[...x,{id,type,title:type==="features"?"Servicios pensados para ti":"Nuestra historia",text:"Añade aquí el contenido de tu sección."}]);A(id);M("Sección añadida.")};
 const update=(key,value)=>SS(items=>items.map(s=>s.id===active?{...s,[key]:value}:s));
 const publish=async()=>{E("");M("");if(!site.hostname.trim()){E("Escribe un dominio para publicar tu web.");return}B(true);try{const r=await api("create",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({hostname:site.hostname.trim().toLowerCase(),title:site.title,description:site.description,framework:"Vanilla",language:"HTML",backend:"Cloudflare Pages Functions",runtime:"Cloudflare",database_type:"SQLite",html:html()})});M("¡Publicado! "+(r.url||("httc://"+site.hostname)));onDone?.()}catch(e){E(e.message||"No se pudo publicar el sitio.")}finally{B(false)}};
 const current=sections.find(s=>s.id===active);
 return <section className="cp-studio"><header className="cp-studio-top"><div className="cp-studio-brand"><button className="cp-back" onClick={()=>navigate("/",onNavigate)}>←</button><div><b>CreatePage <span>Studio</span></b><small>Proyecto web · Diseño visual</small></div></div><div className="cp-studio-top-actions"><span className="cp-save-status"><i/> Vista previa sincronizada</span><button className="cp-secondary" onClick={()=>V(v=>v==="desktop"?"mobile":"desktop")}>{view==="desktop"?"▯ Móvil":"▭ Escritorio"}</button><button className="cp-primary" onClick={publish} disabled={busy}>{busy?"Publicando…":"Publicar sitio ↗"}</button></div></header><div className="cp-studio-workspace"><aside className="cp-studio-panel cp-studio-left"><div className="cp-panel-label">PÁGINA</div><button className="cp-layer active"><span>▤</span><div><b>Inicio</b><small>Landing page</small></div><i>⌄</i></button><div className="cp-panel-label cp-mt">CAPAS Y SECCIONES</div><div className="cp-section-list"><button className={active===1?"selected":""} onClick={()=>A(1)}><span>◈</span><div><b>Hero principal</b><small>Encabezado</small></div></button>{sections.map(s=><button key={s.id} className={active===s.id?"selected":""} onClick={()=>A(s.id)}><span>{s.type==="features"?"▦":"¶"}</span><div><b>{s.type==="features"?"Servicios":"Contenido"}</b><small>{s.title}</small></div></button>)}</div><div className="cp-add-section"><button onClick={()=>add("features")}>＋ Añadir servicios</button><button onClick={()=>add("about")}>＋ Añadir contenido</button></div><div className="cp-left-footer"><span>✦</span><div><b>Diseño adaptable</b><small>Desktop · Tablet · Móvil</small></div></div></aside><div className="cp-canvas-wrap"><div className="cp-canvas-toolbar"><span><i/> Página de inicio <small>/</small></span><div><span>100%</span><button onClick={()=>V(v=>v==="desktop"?"mobile":"desktop")}>{view==="desktop"?"▯":"▭"}</button></div></div><div className="cp-canvas-stage"><div className={"cp-preview "+(view==="mobile"?"is-mobile":"")}><iframe title="Vista previa en directo" srcDoc={html()} sandbox="allow-same-origin"/></div></div><div className="cp-canvas-foot"><span><i/> Vista previa en directo</span><span>Creado con CreatePage</span></div></div><aside className="cp-studio-panel cp-studio-right"><div className="cp-inspector-tabs"><b>Diseño</b><span>Contenido</span><span>Avanzado</span></div><div className="cp-inspector-scroll"><div className="cp-panel-label">IDENTIDAD DEL SITIO</div><label className="cp-field">Nombre del proyecto<input value={site.title} onChange={e=>S(s=>({...s,title:e.target.value}))}/></label><label className="cp-field">Dominio HTTC<input value={site.hostname} onChange={e=>S(s=>({...s,hostname:e.target.value}))}/></label><div className="cp-inspector-divider"/><div className="cp-panel-label">ESTILO GLOBAL</div><label className="cp-field">Color de acento<div className="cp-color-field"><input type="color" value={site.accent} onChange={e=>S(s=>({...s,accent:e.target.value}))}/><code>{site.accent.toUpperCase()}</code></div></label><label className="cp-field">Fondo<div className="cp-color-field"><input type="color" value={site.background} onChange={e=>S(s=>({...s,background:e.target.value}))}/><code>{site.background.toUpperCase()}</code></div></label><label className="cp-field">Color del texto<div className="cp-color-field"><input type="color" value={site.text} onChange={e=>S(s=>({...s,text:e.target.value}))}/><code>{site.text.toUpperCase()}</code></div></label><div className="cp-inspector-divider"/><div className="cp-panel-label">{current?"EDITAR SECCIÓN":"HERO PRINCIPAL"}</div>{current?<><label className="cp-field">Título de sección<textarea value={current.title} onChange={e=>update("title",e.target.value)}/></label><label className="cp-field">Texto<textarea value={current.text} onChange={e=>update("text",e.target.value)}/></label><button className="cp-delete-section" onClick={()=>{SS(x=>x.filter(s=>s.id!==active));A(1)}}>Eliminar sección</button></>:<><label className="cp-field">Antetítulo<input value={site.eyebrow} onChange={e=>S(s=>({...s,eyebrow:e.target.value}))}/></label><label className="cp-field">Titular<textarea value={site.headline} onChange={e=>S(s=>({...s,headline:e.target.value}))}/></label><label className="cp-field">Descripción<textarea value={site.description} onChange={e=>S(s=>({...s,description:e.target.value}))}/></label><label className="cp-field">Texto del botón<input value={site.cta} onChange={e=>S(s=>({...s,cta:e.target.value}))}/></label></>}<div className="cp-inspector-note"><span>✦</span><p><b>Tu visión, tus reglas.</b><br/>Los cambios se reflejan al instante en la vista previa.</p></div>{err&&<div className="cp-error">{err}</div>}{msg&&<div className="cp-success">{msg}</div>}</div></aside></div></section>
}

function DocsPage({path}){return <section className="cp-docs"><small>CREATEPAGE DOCS</small><h1>Documentación</h1><p>HTTC, publicación, Pages, Database y Server.</p><div className="cp-card"><h2>{path}</h2><p>La documentación de CreatePage se sirve bajo <b>docs.createpage.fair</b>.</p></div></section>}
function Empty({text}){return <div className="cp-card cp-empty">{text}</div>}
function NotFound(){return <><Head eyebrow="404" title="Ruta no encontrada"/><Empty text="Esta dirección de CreatePage no existe."/></>}


function PlatformServices({siteId="",siteHostname=""}){
 const[items,setItems]=useState([]),[selected,setSelected]=useState("");
 const[name,setName]=useState("Mi servicio"),[slug,setSlug]=useState("mi-servicio"),[type,setType]=useState("api"),[description,setDescription]=useState("");
 const[domain,setDomain]=useState(siteHostname?"api."+siteHostname:"api.mi-servicio.aploscabluchel"),[domainKind,setDomainKind]=useState("api");
 const[keyLabel,setKeyLabel]=useState("Clave de producción"),[secret,setSecret]=useState("");
 const[routePath,setRoutePath]=useState("/api/status"),[routeMethod,setRouteMethod]=useState("GET"),[routeStatus,setRouteStatus]=useState("200"),[routeAuth,setRouteAuth]=useState(false),[routeJson,setRouteJson]=useState(JSON.stringify({ok:true,service:"{{params.name}}",message:"Fairwas service online"},null,2));
 const[redirectSource,setRedirectSource]=useState("/old"),[redirectTarget,setRedirectTarget]=useState("httc://home"),[redirectStatus,setRedirectStatus]=useState("302");
 const[storageKey,setStorageKey]=useState("config"),[storageValue,setStorageValue]=useState('{"enabled":true}'),[connectionLabel,setConnectionLabel]=useState("Conexión interna"),[targetServiceId,setTargetServiceId]=useState("");
 const[busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState("");
 const selectedService=items.find(x=>x.id===selected)||items[0];
 const request=async(action,body={},method="POST")=>{const [actionName,...extra]=String(action).split("&");const url="/api/platform?action="+encodeURIComponent(actionName)+(extra.length?"&"+extra.join("&"):"");const r=await fetch(url,{method,headers:{"content-type":"application/json"},...(method==="GET"?{}:{body:JSON.stringify(body)})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.detail||d.error||"platform_request_failed");return d};
 const refresh=async(keep)=>{if(!siteId){setItems([]);setSelected("");return}setBusy(true);setError("");try{const d=await request("list&site_id="+encodeURIComponent(siteId),{},"GET");setItems(d.items||[]);const id=keep||selected||d.items?.[0]?.id||"";setSelected((d.items||[]).some(x=>x.id===id)?id:(d.items?.[0]?.id||""))}catch(e){setError(e.message)}finally{setBusy(false)}};
 useEffect(()=>{refresh("")},[siteId]);
 const run=async(fn,msg)=>{setBusy(true);setError("");setNotice("");try{const d=await fn();if(d?.key?.secret)setSecret(d.key.secret);setNotice(msg);await refresh(selected);return d}catch(e){setError(e.message)}finally{setBusy(false)}};
 const createService=()=>run(()=>request("create",{site_id:siteId,name,slug,service_type:type,description}),"Backend creado y vinculado a esta página.");
 const createDomain=()=>run(()=>request("domain-create",{service_id:selectedService?.id,hostname:domain,kind:domainKind}),"Dominio de servicio registrado.");
 const createKey=()=>run(()=>request("key-create",{service_id:selectedService?.id,label:keyLabel,scopes:["api:read","api:write"]}),"Clave generada. Cópiala ahora: no se vuelve a mostrar.");
 const revokeKey=id=>{if(window.confirm("¿Revocar esta clave? Las peticiones que la usen dejarán de funcionar."))run(()=>request("key-revoke",{service_id:selectedService?.id,id}),"Clave revocada.")};
 const createRoute=()=>{let parsed;try{parsed=JSON.parse(routeJson)}catch{setError("La respuesta de la ruta debe ser JSON válido.");return}return run(()=>request("route-create",{service_id:selectedService?.id,path:routePath,method:routeMethod,status_code:Number(routeStatus),response_json:parsed,auth_required:routeAuth}),"Ruta API creada.")};
 const createRedirect=()=>run(()=>request("redirect-create",{service_id:selectedService?.id,source_uri:redirectSource,target_uri:redirectTarget,status_code:Number(redirectStatus)}),"Redirección creada.");
 const remove=(action,id,msg)=>run(()=>request(action,{service_id:selectedService?.id,id}),msg);
 return <><Head eyebrow={siteId?"PROJECT / BACKEND":"PLATFORM / CLOUD"} title={siteId?"Backend y APIs del proyecto":"Cloud y servicios"} text={siteId?"Este backend pertenece a "+siteHostname+". Configura aquí sus subdominios, rutas, cuentas, claves, almacenamiento y conexiones.":"Administra los servicios de tu cuenta."}/>
  <div className="cp-grid two">
   <div className="cp-card cp-form"><h3>＋ Crear el backend de esta página</h3>{!siteId&&<p className="cp-empty">Abre este panel desde el IDE de una página publicada para vincular su backend.</p>}<label>Nombre<input value={name} onChange={e=>setName(e.target.value)} maxLength={80}/></label><label>Identificador<input value={slug} onChange={e=>setSlug(e.target.value)} maxLength={64}/></label><label>Tipo<select value={type} onChange={e=>setType(e.target.value)}>{[["api","API"],["cloud","Cloud / backend"],["identity","Identidad y cuentas"],["storage","Almacenamiento"],["gateway","Gateway / conexiones"]].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Descripción<input value={description} onChange={e=>setDescription(e.target.value)} maxLength={500}/></label><button className="cp-primary" disabled={busy||!siteId} onClick={createService}>Crear backend del proyecto</button></div>
   <div className="cp-card cp-form"><div className="cp-row"><h3>Servicios creados</h3><button onClick={()=>refresh(selected)} disabled={busy}>↻</button></div><label>Servicio activo<select value={selectedService?.id||""} onChange={e=>{setSelected(e.target.value);setSecret("");setNotice("");}}>{items.map(s=><option key={s.id} value={s.id}>{s.name} · {s.service_type}</option>)}</select></label>{selectedService?<><p className="cp-line"><b>Estado</b><span>{selectedService.status}</span></p><p className="cp-line"><b>Slug</b><span>{selectedService.slug}</span></p><p className="cp-line"><b>ID</b><span>{selectedService.id}</span></p><p className="cp-empty">Este ID es la referencia del servicio dentro de Fairwas. Los dominios registrados son URIs HTTC del espacio de nombres Fairwas.</p><button className="cp-site-danger" disabled={busy} onClick={()=>{if(window.confirm("¿Eliminar el servicio y todas sus claves, rutas, dominios y datos almacenados?"))run(()=>request("delete",{service_id:selectedService.id}),"Servicio eliminado.")}}>Eliminar servicio</button></>:<p className="cp-empty">Crea tu primer servicio para configurar la infraestructura.</p>}</div>
  </div>
  {selectedService&&<><div className="cp-grid two">
   <div className="cp-card cp-form"><h3>Dominios y subdominios</h3><label>Hostname<input value={domain} onChange={e=>setDomain(e.target.value)} placeholder="api.miapp.aploscabluchel"/></label><label>Función<select value={domainKind} onChange={e=>setDomainKind(e.target.value)}>{[["api","API"],["auth","Cuentas / identidad"],["storage","Almacenamiento"],["app","Aplicación"],["custom","Personalizado"]].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><button disabled={busy} onClick={createDomain}>＋ Registrar dominio</button><div className="cp-list">{(selectedService.domains||[]).map(d=><div className="cp-line" key={d.id}><span><b>{d.hostname}</b><small>{d.kind}</small></span><button className="cp-site-danger" disabled={busy} onClick={()=>remove("domain-delete",d.id,"Dominio eliminado.")}>Eliminar</button></div>)}</div></div>
   <div className="cp-card cp-form"><h3>Claves API</h3><label>Etiqueta<input value={keyLabel} onChange={e=>setKeyLabel(e.target.value)} maxLength={80}/></label><button disabled={busy} onClick={createKey}>Generar clave secreta</button>{secret&&<div className="cp-key-secret"><b>Guárdala ahora. Solo se muestra una vez.</b><textarea rows={3} readOnly value={secret}/><button onClick={()=>{navigator.clipboard?.writeText(secret);setNotice("Clave copiada si el navegador permite el portapapeles.")}}>Copiar clave</button></div>}<div className="cp-list">{(selectedService.keys||[]).map(k=><div className="cp-line" key={k.id}><span><b>{k.label}</b><small>{k.key_prefix}… · {k.revoked_at?"Revocada":"Activa"}</small></span>{!k.revoked_at&&<button className="cp-site-danger" disabled={busy} onClick={()=>revokeKey(k.id)}>Revocar</button>}</div>)}</div></div>
  </div>
  <div className="cp-grid two">
   <div className="cp-card cp-form"><h3>Rutas de API</h3><div className="cp-grid two"><label>Método<select value={routeMethod} onChange={e=>setRouteMethod(e.target.value)}>{["GET","POST","PUT","PATCH","DELETE"].map(v=><option key={v}>{v}</option>)}</select></label><label>Estado HTTP<select value={routeStatus} onChange={e=>setRouteStatus(e.target.value)}>{[200,201,400,401,403,404,409,422,429,500,503].map(v=><option key={v}>{v}</option>)}</select></label></div><label>Ruta<input value={routePath} onChange={e=>setRoutePath(e.target.value)} placeholder="/api/users/:id"/></label><label>Respuesta JSON<textarea rows={5} value={routeJson} onChange={e=>setRouteJson(e.target.value)} spellCheck={false}/></label><label><input type="checkbox" checked={routeAuth} onChange={e=>setRouteAuth(e.target.checked)}/> Exigir clave API (Bearer)</label><small>Variables: {"{{params.id}}"}, {"{{query.search}}"}, {"{{body.name}}"}.</small><button className="cp-primary" disabled={busy} onClick={createRoute}>＋ Crear ruta</button><div className="cp-list">{(selectedService.routes||[]).map(x=><div className="cp-card" key={x.id}><div className="cp-line"><span><b>{x.method} {x.path}</b><small>HTTP {x.status_code} · {x.auth_required?"Con clave":"Pública"}</small></span><button className="cp-site-danger" disabled={busy} onClick={()=>remove("route-delete",x.id,"Ruta eliminada.")}>Eliminar</button></div>{(selectedService.domains||[]).length>0&&<small>httc://{selectedService.domains[0].hostname}{x.path}</small>}</div>)}</div></div>
   <div className="cp-card cp-form"><h3>URIs y redirecciones</h3><label>Ruta origen<input value={redirectSource} onChange={e=>setRedirectSource(e.target.value)} placeholder="/old-path"/></label><label>Destino HTTC<input value={redirectTarget} onChange={e=>setRedirectTarget(e.target.value)} placeholder="httc://otro-servicio.aploscabluchel/nueva-ruta"/></label><label>Código<select value={redirectStatus} onChange={e=>setRedirectStatus(e.target.value)}>{[301,302,307,308].map(v=><option key={v}>{v}</option>)}</select></label><button disabled={busy} onClick={createRedirect}>＋ Crear redirección</button><div className="cp-list">{(selectedService.redirects||[]).map(x=><div className="cp-card" key={x.id}><b>{x.source_uri} → {x.target_uri}</b><small>HTTP {x.status_code}</small><button className="cp-site-danger" disabled={busy} onClick={()=>remove("redirect-delete",x.id,"Redirección eliminada.")}>Eliminar</button></div>)}</div><p className="cp-empty">Las rutas configuradas se sirven en los dominios del servicio. Las redirecciones usan URIs HTTC propias.</p></div>
  </div>
  <div className="cp-grid two">
   <div className="cp-card cp-form"><h3>Almacenamiento del servicio</h3><label>Clave de almacenamiento<input value={storageKey} onChange={e=>setStorageKey(e.target.value)} placeholder="config/app"/></label><label>Valor JSON<textarea rows={5} value={storageValue} onChange={e=>setStorageValue(e.target.value)} spellCheck={false}/></label><div className="cp-site-actions"><button disabled={busy} onClick={()=>{let value;try{value=JSON.parse(storageValue)}catch{setError("El valor debe ser JSON válido.");return}run(()=>request("storage-set",{service_id:selectedService.id,key:storageKey,value}),"Valor guardado.")}}>Guardar valor</button><button disabled={busy} onClick={()=>run(async()=>{const d=await request("storage-get",{service_id:selectedService.id,key:storageKey});setStorageValue(JSON.stringify(d.value,null,2));return d},"Valor leído.")}>Leer valor</button><button className="cp-site-danger" disabled={busy} onClick={()=>run(()=>request("storage-delete",{service_id:selectedService.id,key:storageKey}),"Valor eliminado.")}>Eliminar</button></div><p className="cp-empty">Almacenamiento clave/valor persistente en D1. No guardes contraseñas ni secretos de usuarios aquí.</p></div>
   <div className="cp-card cp-form"><h3>Conectar servicios</h3><label>Servicio destino<select value={targetServiceId} onChange={e=>setTargetServiceId(e.target.value)}><option value="">Selecciona otro servicio</option>{items.filter(x=>x.id!==selectedService.id).map(x=><option key={x.id} value={x.id}>{x.name} · {x.service_type}</option>)}</select></label><label>Nombre de conexión<input value={connectionLabel} onChange={e=>setConnectionLabel(e.target.value)} maxLength={80}/></label><button disabled={busy||!targetServiceId} onClick={()=>run(()=>request("connection-create",{service_id:selectedService.id,target_service_id:targetServiceId,label:connectionLabel,scopes:["api:read"]}),"Conexión registrada.")}>＋ Crear conexión</button><div className="cp-list">{(selectedService.connections||[]).map(x=><div className="cp-line" key={x.id}><span><b>{x.label}</b><small>Destino: {items.find(s=>s.id===x.target_service_id)?.name||x.target_service_id} · {x.status}</small></span><button className="cp-site-danger" disabled={busy} onClick={()=>remove("connection-delete",x.id,"Conexión eliminada.")}>Desconectar</button></div>)}</div><p className="cp-empty">Las conexiones quedan registradas en la plataforma; el intercambio de credenciales debe usar claves y permisos, nunca secretos en el navegador.</p></div>
  </div>
  </>}
  {error&&<div className="cp-error">{error}</div>}{notice&&<div className="cp-card">{notice}</div>}
 </>;
}
